SELECT chunk_id, kb_id, doc_id, chunk_content, chunk_index, embedding_vector, vector_status, create_time FROM t_rag_chunk_vector WHERE kb_id = #{kbId} AND vector_status = 1
AND 1 - (embedding_vector::vector <=> #{queryVector}::vector) >= #{minSimilarity}
ORDER BY embedding_vector::vector <=> #{queryVector}::vector LIMIT #{topK}
